{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2148-02-17 18:10:00",
      "speaker": "Doctor",
      "text": "Hi Mr. ___, I'm Dr. ___. You were brought in because your nephrostomy tube came out and you're having pain. Can you tell me what happened?"
    },
    {
      "turn_number": 2,
      "time": "2148-02-17 18:12:00",
      "speaker": "Patient",
      "text": "Yeah, I’ve had pain at the site for about a month. Today, the tube started leaking, then it just fell out. I felt a jolt when my wheelchair cushion popped."
    },
    {
      "turn_number": 3,
      "time": "2148-02-17 18:14:00",
      "speaker": "Doctor",
      "text": "I see. And you’re having pain from your left flank down to your lower abdomen, right? Any fever or chills?"
    },
    {
      "turn_number": 4,
      "time": "2148-02-17 18:15:00",
      "speaker": "Patient",
      "text": "Yeah, throbbing pain, worse when I cough. I’ve been feeling hot and cold, and I threw up earlier."
    },
    {
      "turn_number": 5,
      "time": "2148-02-17 18:17:00",
      "speaker": "Doctor",
      "text": "Thanks. We did a CT scan, and it shows your left kidney is swollen because the tube wasn’t draining well. That’s likely why you’re in pain and feeling sick."
    },
    {
      "turn_number": 6,
      "time": "2148-02-17 18:19:00",
      "speaker": "Patient",
      "text": "So the tube wasn’t working even before it fell out?"
    },
    {
      "turn_number": 7,
      "time": "2148-02-17 18:21:00",
      "speaker": "Doctor",
      "text": "Exactly. The tip was in the right place, but it wasn’t draining properly. That can cause infection and kidney stress. We’ve scheduled a procedure to replace it."
    },
    {
      "turn_number": 8,
      "time": "2148-02-17 18:23:00",
      "speaker": "Patient",
      "text": "Will it be more secure this time? It keeps coming loose."
    },
    {
      "turn_number": 9,
      "time": "2148-02-17 18:25:00",
      "speaker": "Doctor",
      "text": "Yes, the interventional radiologist will use extra sutures and a StatLock device to hold it in place better."
    },
    {
      "turn_number": 10,
      "time": "2148-02-17 18:27:00",
      "speaker": "Patient",
      "text": "Okay, good. I don’t want this happening every few months."
    },
    {
      "turn_number": 11,
      "time": "2148-02-17 19:30:00",
      "speaker": "Doctor",
      "text": "Hi again. The tube was successfully replaced. It’s draining well now, and the imaging confirms it’s in the right spot."
    },
    {
      "turn_number": 12,
      "time": "2148-02-17 19:32:00",
      "speaker": "Patient",
      "text": "That’s a relief. Is the infection from the kidney?"
    },
    {
      "turn_number": 13,
      "time": "2148-02-17 19:34:00",
      "speaker": "Doctor",
      "text": "Yes, your urine showed lots of bacteria and white blood cells. We’re calling it pyelonephritis—kidney infection. We’ve started IV antibiotics, meropenem, twice a day."
    },
    {
      "turn_number": 14,
      "time": "2148-02-17 19:36:00",
      "speaker": "Patient",
      "text": "I’ve had that before. Is it the same one?"
    },
    {
      "turn_number": 15,
      "time": "2148-02-17 19:38:00",
      "speaker": "Doctor",
      "text": "Yes, same antibiotic as last time. Your urine culture came back contaminated, so we’re going with what’s worked before."
    },
    {
      "turn_number": 16,
      "time": "2148-02-17 19:40:00",
      "speaker": "Patient",
      "text": "Contaminated? What does that mean?"
    },
    {
      "turn_number": 17,
      "time": "2148-02-17 19:42:00",
      "speaker": "Doctor",
      "text": "It means the sample had skin or genital bacteria, so we can’t trust which bug is really causing the infection. But given your symptoms, we’re treating it seriously."
    },
    {
      "turn_number": 18,
      "time": "2148-02-17 19:44:00",
      "speaker": "Patient",
      "text": "Got it. How long will I be on IV antibiotics?"
    },
    {
      "turn_number": 19,
      "time": "2148-02-17 19:46:00",
      "speaker": "Doctor",
      "text": "Five days total. You’ll get it through your IV twice a day. We’ll monitor your labs to see how you’re responding."
    },
    {
      "turn_number": 20,
      "time": "2148-02-18 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. Your white blood cell count is coming down, which means the infection is responding."
    },
    {
      "turn_number": 21,
      "time": "2148-02-18 08:17:00",
      "speaker": "Patient",
      "text": "That’s good. My pain is better too, especially since the new tube is in."
    },
    {
      "turn_number": 22,
      "time": "2148-02-18 08:19:00",
      "speaker": "Doctor",
      "text": "Great. We also looked at your leg swelling. You mentioned a fall two months ago?"
    },
    {
      "turn_number": 23,
      "time": "2148-02-18 08:21:00",
      "speaker": "Patient",
      "text": "Yeah, I fell getting into my car. My leg’s been swollen since."
    },
    {
      "turn_number": 24,
      "time": "2148-02-18 08:23:00",
      "speaker": "Doctor",
      "text": "The X-ray shows a healing fracture in your left tibia. It’s not new, but it’s still recovering. No need for a brace, but we recommend elevation and compression socks."
    },
    {
      "turn_number": 25,
      "time": "2148-02-18 08:25:00",
      "speaker": "Patient",
      "text": "So it’s not broken now? Just healing?"
    },
    {
      "turn_number": 26,
      "time": "2148-02-18 08:27:00",
      "speaker": "Doctor",
      "text": "Correct. It’s a subacute fracture—meaning it’s in the healing phase. Ortho says no surgery needed. We also checked for blood clots—your ultrasound was negative."
    },
    {
      "turn_number": 27,
      "time": "2148-02-18 08:29:00",
      "speaker": "Patient",
      "text": "Good to know. The swelling’s been worrying me."
    },
    {
      "turn_number": 28,
      "time": "2148-02-19 09:00:00",
      "speaker": "Doctor",
      "text": "Your kidney function is stable. Creatinine is still around 4.0, which is typical for you. We’re watching it daily."
    },
    {
      "turn_number": 29,
      "time": "2148-02-19 09:02:00",
      "speaker": "Patient",
      "text": "Is that because of the tube issue?"
    },
    {
      "turn_number": 30,
      "time": "2148-02-19 09:04:00",
      "speaker": "Doctor",
      "text": "Partly. The blockage made it worse—acute on chronic kidney injury. But now that the tube is working, your kidneys should handle things better."
    },
    {
      "turn_number": 31,
      "time": "2148-02-19 09:06:00",
      "speaker": "Patient",
      "text": "And my blood pressure’s still high. I see it’s up there."
    },
    {
      "turn_number": 32,
      "time": "2148-02-19 09:08:00",
      "speaker": "Doctor",
      "text": "Yes, we’re keeping you on amlodipine. Your pressures are spiking to the 180s, so your outpatient doctor might need to adjust your meds."
    },
    {
      "turn_number": 33,
      "time": "2148-02-20 10:15:00",
      "speaker": "Doctor",
      "text": "We’re planning for discharge tomorrow if all goes well. You’ve had four doses of IV antibiotics. There’s one more due."
    },
    {
      "turn_number": 34,
      "time": "2148-02-20 10:17:00",
      "speaker": "Patient",
      "text": "I’d rather not keep the IV. Can I take pills instead?"
    },
    {
      "turn_number": 35,
      "time": "2148-02-20 10:19:00",
      "speaker": "Doctor",
      "text": "We can switch to oral fosfomycin. It’s the same family—just three doses, every other day. But it’s important you finish all of them."
    },
    {
      "turn_number": 36,
      "time": "2148-02-20 10:21:00",
      "speaker": "Patient",
      "text": "I’ll take the script. I don’t want another infection."
    },
    {
      "turn_number": 37,
      "time": "2148-02-20 10:23:00",
      "speaker": "Doctor",
      "text": "We’ll give you the prescription. We offered to call the pharmacy to check coverage, but you can do it yourself."
    },
    {
      "turn_number": 38,
      "time": "2148-02-20 10:25:00",
      "speaker": "Patient",
      "text": "I’ll handle it. Just give me the script."
    },
    {
      "turn_number": 39,
      "time": "2148-02-21 08:30:00",
      "speaker": "Doctor",
      "text": "Your labs look good. White count is normal. You’re down to just mild tenderness at the tube site."
    },
    {
      "turn_number": 40,
      "time": "2148-02-21 08:32:00",
      "speaker": "Patient",
      "text": "And the leg swelling?"
    },
    {
      "turn_number": 41,
      "time": "2148-02-21 08:34:00",
      "speaker": "Doctor",
      "text": "Better with elevation and compression. Vascular surgery said no concern for compartment syndrome. Keep wearing the socks."
    },
    {
      "turn_number": 42,
      "time": "2148-02-21 08:36:00",
      "speaker": "Patient",
      "text": "What about my hip wound? It’s not getting better."
    },
    {
      "turn_number": 43,
      "time": "2148-02-21 08:38:00",
      "speaker": "Doctor",
      "text": "Wound care checked it. It’s a chronic ulcer, not infected now. They recommend continuing home care. Surgery isn’t an option right now."
    },
    {
      "turn_number": 44,
      "time": "2148-02-21 08:40:00",
      "speaker": "Patient",
      "text": "Okay. I’ll keep cleaning it like before."
    },
    {
      "turn_number": 45,
      "time": "2148-02-22 09:00:00",
      "speaker": "Doctor",
      "text": "You’re cleared to go home. We’ll review your discharge instructions."
    },
    {
      "turn_number": 46,
      "time": "2148-02-22 09:02:00",
      "speaker": "Patient",
      "text": "Great. What do I need to do?"
    },
    {
      "turn_number": 47,
      "time": "2148-02-22 09:04:00",
      "speaker": "Doctor",
      "text": "First, take the fosfomycin—three doses, every other day. It’s critical to finish all of them to prevent the infection from coming back."
    },
    {
      "turn_number": 48,
      "time": "2148-02-22 09:06:00",
      "speaker": "Patient",
      "text": "I understand. I’ll do it."
    },
    {
      "turn_number": 49,
      "time": "2148-02-22 09:08:00",
      "speaker": "Doctor",
      "text": "Second, call interventional radiology to schedule your next tube check in a few months. We gave you extra drainage bags and a StatLock to help prevent dislodgement."
    },
    {
      "turn_number": 50,
      "time": "2148-02-22 09:10:00",
      "speaker": "Patient",
      "text": "I’ll call them today."
    },
    {
      "turn_number": 51,
      "time": "2148-02-22 09:12:00",
      "speaker": "Doctor",
      "text": "Also, keep elevating your left leg and wearing the compression socks. Follow up with ortho in a month for another X-ray."
    },
    {
      "turn_number": 52,
      "time": "2148-02-22 09:14:00",
      "speaker": "Patient",
      "text": "Got it. And my regular meds?"
    },
    {
      "turn_number": 53,
      "time": "2148-02-22 09:16:00",
      "speaker": "Doctor",
      "text": "Yes, continue all your home medications—pain, seizure, anxiety, and kidney meds. Your blood pressure is still high, so talk to your doctor about adjusting it."
    },
    {
      "turn_number": 54,
      "time": "2148-02-22 09:18:00",
      "speaker": "Patient",
      "text": "I will. Thanks for everything."
    },
    {
      "turn_number": 55,
      "time": "2148-02-22 09:20:00",
      "speaker": "Doctor",
      "text": "You’re welcome. If you develop fever, increased pain, or the tube comes out again, come back right away."
    },
    {
      "turn_number": 56,
      "time": "2148-02-22 09:22:00",
      "speaker": "Patient",
      "text": "I will. I don’t want to be back here soon."
    },
    {
      "turn_number": 57,
      "time": "2148-02-22 09:24:00",
      "speaker": "Doctor",
      "text": "We’ve updated your care team and your mother is listed as your health care proxy. Call us with any concerns."
    },
    {
      "turn_number": 58,
      "time": "2148-02-22 09:26:00",
      "speaker": "Patient",
      "text": "I’ll keep the number handy."
    },
    {
      "turn_number": 59,
      "time": "2148-02-22 09:28:00",
      "speaker": "Doctor",
      "text": "Alright, the discharge papers are ready. A nurse will go over them with you one more time before you leave."
    },
    {
      "turn_number": 60,
      "time": "2148-02-22 09:30:00",
      "speaker": "Patient",
      "text": "Thanks, doc. I feel a lot better."
    },
    {
      "turn_number": 61,
      "time": "2148-02-22 09:32:00",
      "speaker": "Doctor",
      "text": "Glad to hear it. Take care, and we’ll see you in follow-up if needed."
    },
    {
      "turn_number": 62,
      "time": "2148-02-22 09:34:00",
      "speaker": "Patient",
      "text": "Will do."
    },
    {
      "turn_number": 63,
      "time": "2148-02-22 09:36:00",
      "speaker": "Doctor",
      "text": "One last thing—your urine tested positive for cocaine. You mentioned you didn’t use it. Is that correct?"
    },
    {
      "turn_number": 64,
      "time": "2148-02-22 09:38:00",
      "speaker": "Patient",
      "text": "Yeah, I haven’t used in months. Maybe it’s from old residue or something."
    },
    {
      "turn_number": 65,
      "time": "2148-02-22 09:40:00",
      "speaker": "Doctor",
      "text": "Okay, we’ll note that. Just wanted to check in case you needed support."
    },
    {
      "turn_number": 66,
      "time": "2148-02-22 09:42:00",
      "speaker": "Patient",
      "text": "I appreciate it. I’m clean now."
    },
    {
      "turn_number": 67,
      "time": "2148-02-22 09:44:00",
      "speaker": "Doctor",
      "text": "Good to hear. Stay well."
    }
  ],
  "summary": {
    "admission_start": "2148-02-17 18:06:00",
    "admission_end": "2148-02-22 11:57:00",
    "summary_paragraph": "Mr. ___ was admitted with a dislodged nephrostomy tube, left flank pain, and signs of kidney infection. Imaging confirmed severe left hydroureteronephrosis due to tube dysfunction. He underwent successful nephrostomy tube exchange with secure fixation. He was treated with IV meropenem for pyelonephritis, though he declined the final IV dose and oral antibiotic initiation in the hospital. He was discharged with a prescription for oral fosfomycin to complete the course. His chronic left hip wound was monitored, and leg swelling was evaluated, revealing a subacute tibial fracture without need for intervention. Renal function remained stable, and he was discharged home with follow-up instructions for urology, orthopedics, and medication adherence.",
    "problems": [
      "Infection of incontinent external stoma of urinary tract",
      "Pressure ulcer of left hip, stage 4",
      "Chronic kidney disease, stage 4 (severe)",
      "Paraplegia, incomplete",
      "Acute kidney failure, unspecified",
      "Pyonephrosis",
      "Other neuromuscular dysfunction of bladder",
      "Hypertensive chronic kidney disease with stage 1 through stage 4 chronic kidney disease, or unspecified chronic kidney disease",
      "Cocaine use, unspecified, uncomplicated",
      "Anxiety disorder, unspecified",
      "Insomnia, unspecified",
      "Gastro-esophageal reflux disease without esophagitis",
      "Other fracture of upper end of left tibia, subsequent encounter for closed fracture with routine healing",
      "Unspecified fall, subsequent encounter"
    ]
  }
}
